import { AwsClient } from "aws4fetch";
import { awsEndpoint, requireCommercialRegion, type AwsService } from "./regions.ts";
import { isXmlObject, parseAwsXml, type XmlObject } from "./xml.ts";

export interface AwsAccount {
  readonly fields: {
    readonly accessKeyId: string;
    readonly secretAccessKey: string;
    readonly sessionToken?: string;
    readonly region: string;
  };
}

export interface Invocation {
  readonly fetch: (input: string | URL | Request, init?: RequestInit) => Promise<Response>;
  readonly signal: AbortSignal;
}

export interface CallerIdentity {
  readonly accountId: string;
  readonly arn: string;
  readonly userId: string;
}

export interface S3Bucket {
  readonly name: string;
  readonly creationDate?: string;
}

export interface BucketPage {
  readonly region: string;
  readonly buckets: readonly S3Bucket[];
  readonly nextContinuationToken?: string;
}

export class AwsHttpError extends Error {
  readonly service: AwsService;
  readonly status: number;

  constructor(service: AwsService, status: number, redirected = false) {
    const name = service === "sts" ? "STS" : "S3";
    super(
      redirected
        ? "AWS " + name + " redirected the request with HTTP " + status + "."
        : "AWS " + name + " request failed with HTTP " + status + ".",
    );
    this.name = "AwsHttpError";
    this.service = service;
    this.status = status;
  }
}

function redactCredentials(value: string, account: AwsAccount): string {
  const credentials = [
    account.fields.accessKeyId,
    account.fields.secretAccessKey,
    account.fields.sessionToken,
  ];
  let safe = value;
  for (const credential of credentials) {
    if (credential !== undefined && credential.length > 0) {
      safe = safe.replaceAll(credential, "[redacted]");
    }
  }
  return safe;
}

async function signedResponse(
  account: AwsAccount,
  service: AwsService,
  region: string,
  invocation: Invocation,
  init: RequestInit,
  query: readonly (readonly [string, string])[] = [],
): Promise<Response> {
  const url = new URL(awsEndpoint(service, region));
  for (const [name, value] of query) {
    url.searchParams.set(name, value);
  }

  let signedRequest: Request;
  try {
    const client = new AwsClient({
      accessKeyId: account.fields.accessKeyId,
      secretAccessKey: account.fields.secretAccessKey,
      ...(account.fields.sessionToken === undefined
        ? {}
        : { sessionToken: account.fields.sessionToken }),
      service,
      region,
    });
    signedRequest = await client.sign(
      new Request(url, {
        ...init,
        redirect: "manual",
      }),
    );
  } catch {
    throw new Error("AWS request signing failed.");
  }

  let response: Response;
  try {
    response = await invocation.fetch(signedRequest, {
      signal: invocation.signal,
      redirect: "manual",
    });
  } catch {
    throw new Error("AWS request to the fixed endpoint failed.");
  }

  if (response.status >= 300 && response.status < 400) {
    throw new AwsHttpError(service, response.status, true);
  }
  if (!response.ok) {
    throw new AwsHttpError(service, response.status);
  }
  return response;
}

async function parseResponse(response: Response, service: AwsService): Promise<XmlObject> {
  try {
    return parseAwsXml(await response.text());
  } catch {
    const name = service === "sts" ? "STS" : "S3";
    throw new Error("AWS " + name + " returned an invalid XML response.");
  }
}

function child(value: unknown, key: string): unknown {
  return isXmlObject(value) ? value[key] : undefined;
}

function requiredText(value: unknown, key: string): string {
  const field = child(value, key);
  if (typeof field !== "string" || field.length === 0) {
    throw new Error("AWS returned an unexpected response.");
  }
  return field;
}

export async function getCallerIdentity(
  account: AwsAccount,
  invocation: Invocation,
): Promise<CallerIdentity> {
  const region = requireCommercialRegion(account.fields.region);
  const response = await signedResponse(account, "sts", region, invocation, {
    method: "POST",
    headers: {
      accept: "text/xml",
      "content-type": "application/x-www-form-urlencoded",
    },
    body: "Action=GetCallerIdentity&Version=2011-06-15",
  });
  const document = await parseResponse(response, "sts");
  const result = child(child(document, "GetCallerIdentityResponse"), "GetCallerIdentityResult");
  const accountId = requiredText(result, "Account");
  const arn = requiredText(result, "Arn");
  const userId = requiredText(result, "UserId");
  if (!/^\d{12}$/.test(accountId)) {
    throw new Error("AWS returned an unexpected caller identity.");
  }
  return {
    accountId: redactCredentials(accountId, account),
    arn: redactCredentials(arn, account),
    userId: redactCredentials(userId, account),
  };
}

export async function listBuckets(
  account: AwsAccount,
  invocation: Invocation,
  continuationToken?: string,
): Promise<BucketPage> {
  const region = requireCommercialRegion(account.fields.region);
  if (continuationToken !== undefined && continuationToken.length > 1024) {
    throw new Error("The S3 continuation token must be 1,024 characters or fewer.");
  }

  const query: (readonly [string, string])[] = [
    ["bucket-region", region],
    ["max-buckets", "1000"],
  ];
  if (continuationToken !== undefined) {
    query.push(["continuation-token", continuationToken]);
  }

  const response = await signedResponse(account, "s3", region, invocation, { method: "GET" }, query);
  const document = await parseResponse(response, "s3");
  const result = child(document, "ListAllMyBucketsResult");
  const bucketGroup = child(result, "Buckets");
  const entries = child(bucketGroup, "Bucket");
  const rawBuckets = entries === undefined || entries === "" ? [] : Array.isArray(entries) ? entries : [entries];
  const buckets = rawBuckets.map((entry): S3Bucket => {
    if (!isXmlObject(entry)) {
      throw new Error("AWS returned an unexpected bucket list.");
    }
    const name = requiredText(entry, "Name");
    const creationDate = child(entry, "CreationDate");
    if (creationDate !== undefined && typeof creationDate !== "string") {
      throw new Error("AWS returned an unexpected bucket list.");
    }
    return {
      name: redactCredentials(name, account),
      ...(typeof creationDate === "string" && creationDate.length > 0
        ? { creationDate: redactCredentials(creationDate, account) }
        : {}),
    };
  });
  const rawToken = child(result, "ContinuationToken");
  if (rawToken !== undefined && typeof rawToken !== "string") {
    throw new Error("AWS returned an unexpected bucket list.");
  }
  return {
    region,
    buckets,
    ...(typeof rawToken === "string" && rawToken.length > 0
      ? { nextContinuationToken: redactCredentials(rawToken, account) }
      : {}),
  };
}

import { object, plain, raw, secrets, string } from "apps";

export const awsCredentialFields = object({
  accessKeyId: raw(string({ minLength: 1 })),
  secretAccessKey: raw(string({ minLength: 1 })),
  sessionToken: raw(string({ minLength: 1 })).optional(),
  region: plain(string({ minLength: 1 })),
});

export const awsCredentials = secrets({
  label: "AWS access keys",
  fields: awsCredentialFields,
});

import {
  accountRouter,
  array,
  defineApp,
  defineProvider,
  object,
  ProviderError,
  query,
  router,
  string,
} from "apps";
import { AwsHttpError, getCallerIdentity, listBuckets } from "./aws.ts";
import { awsCredentials } from "./credentials.ts";
import { awsHosts } from "./regions.ts";

const CallerIdentityOutput = object({
  accountId: string(),
  arn: string(),
  userId: string(),
});

const Bucket = object({
  name: string(),
  creationDate: string().optional(),
});

const BucketPageOutput = object({
  region: string(),
  buckets: array(Bucket),
  nextContinuationToken: string().optional(),
});

const ListBucketsInput = object({
  continuationToken: string().optional(),
});

function healthFailure(error: unknown): never {
  if (error instanceof AwsHttpError) {
    const reason =
      error.status === 401
        ? "unauthorized"
        : error.status === 429
          ? "rate_limited"
          : error.status >= 500
            ? "unavailable"
            : "rejected";
    throw new ProviderError({ reason, status: error.status });
  }
  throw error;
}

export const awsProvider = defineProvider({
  name: "AWS",
  hosts: awsHosts,
  auth: { credentials: awsCredentials },
  async health({ account, fetch, signal }) {
    try {
      const identity = await getCallerIdentity(account, { fetch, signal });
      return {
        accountInfo: {
          externalId: identity.arn,
          displayName: identity.arn,
        },
      };
    } catch (error) {
      healthFailure(error);
    }
  },
});

const requirements = {
  user: { accounts: { aws: awsProvider.many() } },
};

export default defineApp(requirements, async ({ user, fetch, signal }) => ({
  tools: router(
    await accountRouter(
      user?.accounts.aws ?? [],
      (account) =>
        router({
          getCallerIdentity: query(
            {
              description: "Get the AWS identity for this connected credential set.",
              input: object({}),
              output: CallerIdentityOutput,
            },
            () => getCallerIdentity(account, { fetch, signal }),
          ),
          listBuckets: query(
            {
              description:
                "List up to 1,000 general-purpose S3 buckets in this connection's configured region. " +
                "Use a returned continuation token to read the next page.",
              input: ListBucketsInput,
              output: BucketPageOutput,
            },
            (_context, { continuationToken }) =>
              listBuckets(account, { fetch, signal }, continuationToken),
          ),
        }),
      { signal },
    ),
    {
      title: "AWS",
      description: "Read AWS caller identity and list S3 buckets with each connected user's own access keys.",
    },
  ),
}));

export const commercialRegions = [
  "af-south-1",
  "ap-east-1",
  "ap-east-2",
  "ap-northeast-1",
  "ap-northeast-2",
  "ap-northeast-3",
  "ap-south-1",
  "ap-south-2",
  "ap-southeast-1",
  "ap-southeast-2",
  "ap-southeast-3",
  "ap-southeast-4",
  "ap-southeast-5",
  "ap-southeast-6",
  "ap-southeast-7",
  "ca-central-1",
  "ca-west-1",
  "eu-central-1",
  "eu-central-2",
  "eu-north-1",
  "eu-south-1",
  "eu-south-2",
  "eu-west-1",
  "eu-west-2",
  "eu-west-3",
  "il-central-1",
  "me-central-1",
  "me-south-1",
  "mx-central-1",
  "sa-east-1",
  "us-east-1",
  "us-east-2",
  "us-west-1",
  "us-west-2",
] as const;

export type CommercialRegion = (typeof commercialRegions)[number];
export type AwsService = "s3" | "sts";

const commercialRegionSet: ReadonlySet<string> = new Set(commercialRegions);

export const awsHosts = commercialRegions.flatMap((region) => [
  "sts." + region + ".amazonaws.com",
  "s3." + region + ".amazonaws.com",
]);

export function requireCommercialRegion(region: string): CommercialRegion {
  if (!commercialRegionSet.has(region)) {
    throw new Error("Choose a supported AWS commercial region.");
  }
  return region as CommercialRegion;
}

export function awsEndpoint(service: AwsService, region: string): string {
  return "https://" + service + "." + requireCommercialRegion(region) + ".amazonaws.com/";
}

import { XMLParser, XMLValidator } from "fast-xml-parser";

export type XmlObject = Record<string, unknown>;

export function isXmlObject(value: unknown): value is XmlObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseAwsXml(source: string): XmlObject {
  try {
    if (XMLValidator.validate(source) !== true) {
      throw new Error("invalid XML");
    }
    const parsed: unknown = new XMLParser({
      ignoreAttributes: true,
      parseTagValue: false,
      trimValues: true,
    }).parse(source);
    if (!isXmlObject(parsed)) {
      throw new Error("invalid XML");
    }
    return parsed;
  } catch {
    throw new Error("AWS returned an invalid XML response.");
  }
}

